  c += uSkySun * (pow(s, 16.0) * 0.55 + pow(s, 260.0) * 1.4) * (1.0 - 0.58 * uLook);
  if (el < 0.0) c = mix(c, uSkyHorizon * 0.5, smoothstep(0.0, -0.25, el));
